import { sql } from "drizzle-orm";
import { index, integer, primaryKey, sqliteTable, text, unique } from "drizzle-orm/sqlite-core";

/*
 * Support tables for SQLite and Cloudflare D1. Same shape as the Postgres schema: ids that point
 * into your product (customer, user, agent) are text, timestamps are epoch milliseconds.
 */

const id = () =>
  text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID());
const ms = (name: string) => integer(name, { mode: "timestamp_ms" });
const now = sql`(cast(unixepoch('subsecond') * 1000 as integer))`;
const createdAt = () => ms("created_at").notNull().default(now);
const updatedAt = () => ms("updated_at").notNull().default(now);
type AddressJson = { address: string; name?: string | null };

export const supportContacts = sqliteTable(
  "support_contacts",
  {
    id: id(),
    name: text("name"),
    customerId: text("customer_id"),
    userId: text("user_id"),
    locale: text("locale"),
    blockedAt: ms("blocked_at"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("support_contacts_customer_idx").on(t.customerId), index("support_contacts_user_idx").on(t.userId)]
);

export const supportContactIdentities = sqliteTable(
  "support_contact_identities",
  {
    id: id(),
    contactId: text("contact_id")
      .notNull()
      .references(() => supportContacts.id, { onDelete: "cascade" }),
    kind: text("kind").notNull(),
    value: text("value").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    unique("support_contact_identities_kind_value").on(t.kind, t.value),
    index("support_contact_identities_contact_idx").on(t.contactId),
  ]
);

export const supportTickets = sqliteTable(
  "support_tickets",
  {
    id: id(),
    /** Assigned by the store as max + 1; unique, so a concurrent insert retries. */
    number: integer("number").notNull(),
    channelId: text("channel_id").notNull(),
    subject: text("subject"),
    status: text("status").notNull(),
    contactId: text("contact_id")
      .notNull()
      .references(() => supportContacts.id),
    customerId: text("customer_id"),
    assigneeId: text("assignee_id"),
    replyToken: text("reply_token").notNull(),
    providerThreadId: text("provider_thread_id"),
    waitingSince: ms("waiting_since"),
    lastMessageAt: ms("last_message_at").notNull(),
    lastInboundAt: ms("last_inbound_at"),
    lastOutboundAt: ms("last_outbound_at"),
    solvedAt: ms("solved_at"),
    preview: text("preview"),
    previewKind: text("preview_kind"),
    previewAuthorId: text("preview_author_id"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique("support_tickets_number").on(t.number),
    unique("support_tickets_reply_token").on(t.replyToken),
    index("support_tickets_status_waiting_idx").on(t.status, t.waitingSince),
    index("support_tickets_status_recent_idx").on(t.status, t.lastMessageAt),
    index("support_tickets_customer_idx").on(t.customerId, t.lastMessageAt),
    index("support_tickets_contact_idx").on(t.contactId, t.channelId),
    index("support_tickets_thread_idx").on(t.channelId, t.providerThreadId),
    /* Insights (0005_insights.sql): a period's tickets are found by when they were opened and solved. */
    index("support_tickets_created_idx").on(t.createdAt),
    index("support_tickets_solved_idx").on(t.solvedAt),
  ]
);

export const supportMessages = sqliteTable(
  "support_messages",
  {
    id: id(),
    ticketId: text("ticket_id")
      .notNull()
      .references(() => supportTickets.id, { onDelete: "cascade" }),
    kind: text("kind").notNull(),
    channelId: text("channel_id"),
    authorId: text("author_id"),
    from: text("from", { mode: "json" }).$type<AddressJson | null>(),
    to: text("to", { mode: "json" }).$type<AddressJson[]>().notNull().default(sql`'[]'`),
    cc: text("cc", { mode: "json" }).$type<AddressJson[]>().notNull().default(sql`'[]'`),
    subject: text("subject"),
    text: text("text").notNull(),
    fullText: text("full_text"),
    html: text("html"),
    rfcMessageId: text("rfc_message_id"),
    inReplyTo: text("in_reply_to"),
    references: text("references", { mode: "json" }).$type<string[]>().notNull().default(sql`'[]'`),
    providerMessageId: text("provider_message_id"),
    deliveryStatus: text("delivery_status"),
    deliveryError: text("delivery_error"),
    auto: integer("auto", { mode: "boolean" }).notNull().default(false),
    source: text("source").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    unique("support_messages_provider_id").on(t.channelId, t.providerMessageId),
    index("support_messages_ticket_idx").on(t.ticketId, t.createdAt),
    index("support_messages_rfc_idx").on(t.rfcMessageId),
  ]
);

export const supportAttachments = sqliteTable(
  "support_attachments",
  {
    id: id(),
    messageId: text("message_id").references(() => supportMessages.id, { onDelete: "cascade" }),
    ticketId: text("ticket_id").references(() => supportTickets.id, { onDelete: "cascade" }),
    uploadedBy: text("uploaded_by"),
    filename: text("filename").notNull(),
    contentType: text("content_type").notNull(),
    size: integer("size").notNull(),
    storageKey: text("storage_key").notNull(),
    contentId: text("content_id"),
    inline: integer("inline", { mode: "boolean" }).notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [index("support_attachments_message_idx").on(t.messageId)]
);

export const supportEvents = sqliteTable(
  "support_events",
  {
    id: id(),
    ticketId: text("ticket_id")
      .notNull()
      .references(() => supportTickets.id, { onDelete: "cascade" }),
    type: text("type").notNull(),
    actorId: text("actor_id"),
    data: text("data", { mode: "json" }).$type<Record<string, unknown>>().notNull().default(sql`'{}'`),
    createdAt: createdAt(),
  },
  (t) => [
    index("support_events_ticket_idx").on(t.ticketId, t.createdAt),
    /* Insights (0005_insights.sql): reopened tickets in a period. */
    index("support_events_type_idx").on(t.type, t.createdAt),
  ]
);

export const supportReads = sqliteTable(
  "support_reads",
  {
    ticketId: text("ticket_id")
      .notNull()
      .references(() => supportTickets.id, { onDelete: "cascade" }),
    readerId: text("reader_id").notNull(),
    readAt: ms("read_at").notNull(),
  },
  (t) => [primaryKey({ columns: [t.ticketId, t.readerId] })]
);

export const supportChannelState = sqliteTable("support_channel_state", {
  channelId: text("channel_id").primaryKey(),
  state: text("state", { mode: "json" }).$type<Record<string, unknown>>().notNull(),
  lastError: text("last_error"),
  updatedAt: updatedAt(),
});

import { and, asc, count, desc, eq, exists, gte, inArray, isNull, like, lt, ne, or, sql, type SQL } from "drizzle-orm";
import type { BaseSQLiteDatabase } from "drizzle-orm/sqlite-core";
import type { SupportStore, TicketCounts } from "../store";
import type { Attachment, Contact, Identity, Message, Ticket, TicketEvent } from "../types";
import {
  supportAttachments,
  supportChannelState,
  supportContactIdentities,
  supportContacts,
  supportEvents,
  supportMessages,
  supportReads,
  supportTickets,
} from "./schema";
import { periodBreakdown, periodTotals } from "./stats";

// Any Drizzle SQLite database that runs queries asynchronously: D1, libSQL, a proxy.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Db = BaseSQLiteDatabase<"async", any, any>;

const escapeLike = (value: string) => value.replace(/[\\%_]/g, (c) => `\\${c}`);

/**
 * The store for SQLite and Cloudflare D1.
 *
 * D1 has no interactive transactions, so `transaction` compensates instead: it records the tickets
 * and messages created inside it and deletes them if the function throws. That covers what the
 * service needs (a duplicate email arriving twice at once never leaves half a ticket behind);
 * updates made before the failure are not reverted.
 */
export function createD1Store(db: Db): SupportStore {
  return buildStore(db, null);
}

type Created = { tickets: string[]; messages: string[] };

function buildStore(db: Db, created: Created | null): SupportStore {
  const store: SupportStore = {
    async transaction(fn) {
      const log: Created = { tickets: [], messages: [] };
      try {
        return await fn(buildStore(db, log));
      } catch (error) {
        if (log.messages.length) await db.delete(supportMessages).where(inArray(supportMessages.id, log.messages));
        if (log.tickets.length) await db.delete(supportTickets).where(inArray(supportTickets.id, log.tickets));
        throw error;
      }
    },

    async findContactByIdentity(identity) {
      const [row] = await db
        .select({ contactId: supportContactIdentities.contactId })
        .from(supportContactIdentities)
        .where(and(eq(supportContactIdentities.kind, identity.kind), eq(supportContactIdentities.value, identity.value)))
        .limit(1);
      return row ? store.getContact(row.contactId) : null;
    },

    async getContact(id) {
      const [contact] = await store.getContacts([id]);
      return contact ?? null;
    },

    async getContacts(ids) {
      if (!ids.length) return [];
      const rows = await db.select().from(supportContacts).where(inArray(supportContacts.id, ids));
      const identities = await db.select().from(supportContactIdentities).where(inArray(supportContactIdentities.contactId, ids));
      return rows.map((row) => toContact(row, identities.filter((i) => i.contactId === row.id)));
    },

    async listContacts(query) {
      const search = query.search?.trim().replace(/[\\%_]/g, "\\$&");
      const rows = await db
        .select({ id: supportContacts.id })
        .from(supportContacts)
        .where(
          and(
            query.customerId ? eq(supportContacts.customerId, query.customerId) : undefined,
            query.userId ? eq(supportContacts.userId, query.userId) : undefined,
            search
              ? or(
                  like(supportContacts.name, `%${search}%`),
                  sql`exists (select 1 from ${supportContactIdentities} i where i.contact_id = ${supportContacts.id} and i.value like ${`%${search.toLowerCase()}%`})`
                )
              : undefined
          )
        )
        .orderBy(desc(supportContacts.updatedAt), desc(supportContacts.id))
        .limit(query.limit);
      const contacts = await store.getContacts(rows.map((row) => row.id));
      const order = new Map(rows.map((row, index) => [row.id, index]));
      return contacts.sort((a, b) => order.get(a.id)! - order.get(b.id)!);
    },

    async createContact(input) {
      const [row] = await db
        .insert(supportContacts)
        .values({ name: input.name, customerId: input.customerId, userId: input.userId, locale: input.locale })
        .returning();
      for (const identity of input.identities) await store.addIdentity(row!.id, identity);
      return (await store.getContact(row!.id))!;
    },

    async updateContact(id, patch) {
      await db.update(supportContacts).set({ ...patch, updatedAt: new Date() }).where(eq(supportContacts.id, id));
    },

    async addIdentity(contactId, identity) {
      await db
        .insert(supportContactIdentities)
        .values({ contactId, kind: identity.kind, value: identity.value })
        .onConflictDoNothing();
    },

    async getTicket(id) {
      const [row] = await db.select().from(supportTickets).where(eq(supportTickets.id, id)).limit(1);
      return (row as Ticket | undefined) ?? null;
    },

    async findTicketByToken(token) {
      const [row] = await db.select().from(supportTickets).where(eq(supportTickets.replyToken, token)).limit(1);
      return (row as Ticket | undefined) ?? null;
    },

    async findTicketByRfcMessageIds(ids) {
      if (!ids.length) return null;
      const [row] = await db
        .select({ ticketId: supportMessages.ticketId })
        .from(supportMessages)
        .where(inArray(supportMessages.rfcMessageId, ids))
        .orderBy(desc(supportMessages.createdAt))
        .limit(1);
      return row ? store.getTicket(row.ticketId) : null;
    },

    async findTicketByProviderThread(channelId, providerThreadId) {
      const [row] = await db
        .select()
        .from(supportTickets)
        .where(and(eq(supportTickets.channelId, channelId), eq(supportTickets.providerThreadId, providerThreadId)))
        .orderBy(desc(supportTickets.lastMessageAt))
        .limit(1);
      return (row as Ticket | undefined) ?? null;
    },

    async findLatestTicket(channelId, contactId) {
      const [row] = await db
        .select()
        .from(supportTickets)
        .where(and(eq(supportTickets.channelId, channelId), eq(supportTickets.contactId, contactId)))
        .orderBy(desc(supportTickets.lastMessageAt))
        .limit(1);
      return (row as Ticket | undefined) ?? null;
    },

    async createTicket(input) {
      // SQLite has no sequences: the next number is max + 1, retried if another insert takes it.
      for (let attempt = 0; ; attempt++) {
        try {
          const [row] = await db
            .insert(supportTickets)
            .values({
              ...input,
              number: sql`(select coalesce(max(${supportTickets.number}), 0) + 1 from ${supportTickets})`,
              lastMessageAt: input.createdAt,
              createdAt: input.createdAt,
              updatedAt: input.createdAt,
            })
            .returning();
          created?.tickets.push(row!.id);
          return row as Ticket;
        } catch (error) {
          if (attempt >= 4 || !/UNIQUE constraint failed: support_tickets\.number/i.test(String(error))) throw error;
        }
      }
    },

    async linkContactTickets(contactId, customerId) {
      await db
        .update(supportTickets)
        .set({ customerId, updatedAt: new Date() })
        .where(and(eq(supportTickets.contactId, contactId), isNull(supportTickets.customerId)));
    },

    async updateTicket(id, patch) {
      const [row] = await db
        .update(supportTickets)
        .set({ ...patch, updatedAt: new Date() })
        .where(eq(supportTickets.id, id))
        .returning();
      if (!row) throw new Error(`Ticket ${id} not found`);
      return row as Ticket;
    },

    async listTickets(query) {
      const where = and(...ticketFilters(query));
      const order =
        query.sort === "waiting"
          ? [sql`${supportTickets.waitingSince} asc nulls last`, desc(supportTickets.lastMessageAt)]
          : query.sort === "priority"
            ? [
                // Raw SQL, so this file doesn't depend on the AI schema. Tickets without an insight count as normal.
                sql`coalesce((select urgency_rank from support_ticket_insights where support_ticket_insights.ticket_id = ${supportTickets.id}), 2) asc`,
                sql`${supportTickets.waitingSince} asc nulls last`,
                desc(supportTickets.lastMessageAt),
              ]
          : query.sort === "solved"
            ? [sql`${supportTickets.solvedAt} desc nulls last`]
            : [desc(supportTickets.lastMessageAt)];
      const items = await db
        .select()
        .from(supportTickets)
        .where(where)
        .orderBy(...order, desc(supportTickets.number))
        .limit(query.limit)
        .offset(query.offset);
      const [total] = await db.select({ value: count() }).from(supportTickets).where(where);
      return { items: items as Ticket[], total: Number(total?.value ?? 0) };
    },

    async countTickets({ assigneeId }) {
      const rows = await db
        .select({
          status: supportTickets.status,
          total: count(),
          unassigned: sql<number>`sum(case when ${supportTickets.assigneeId} is null then 1 else 0 end)`.mapWith(Number),
          mine: assigneeId
            ? sql<number>`sum(case when ${supportTickets.assigneeId} = ${assigneeId} then 1 else 0 end)`.mapWith(Number)
            : sql<number>`0`.mapWith(Number),
        })
        .from(supportTickets)
        .groupBy(supportTickets.status);
      const counts: TicketCounts = { open: 0, waiting: 0, solved: 0, spam: 0, unassigned: 0, mine: 0 };
      for (const row of rows) {
        counts[row.status as keyof TicketCounts] = Number(row.total);
        if (row.status === "open") {
          counts.unassigned = row.unassigned;
          counts.mine = row.mine;
        }
      }
      return counts;
    },

    async insertMessage(input) {
      const [row] = await db
        .insert(supportMessages)
        .values(input)
        .onConflictDoNothing({ target: [supportMessages.channelId, supportMessages.providerMessageId] })
        .returning();
      if (!row) return null;
      created?.messages.push(row.id);
      return toMessage(row, []);
    },

    async updateMessage(id, patch) {
      await db.update(supportMessages).set(patch).where(eq(supportMessages.id, id));
    },

    async getMessage(id) {
      const [row] = await db.select().from(supportMessages).where(eq(supportMessages.id, id)).limit(1);
      if (!row) return null;
      const attachments = await db.select().from(supportAttachments).where(eq(supportAttachments.messageId, id));
      return toMessage(row, attachments);
    },

    async findMessageByProviderId(channelId, providerMessageId) {
      const [row] = await db
        .select()
        .from(supportMessages)
        .where(and(eq(supportMessages.channelId, channelId), eq(supportMessages.providerMessageId, providerMessageId)))
        .limit(1);
      return row ? toMessage(row, []) : null;
    },

    async listMessages(ticketId, { includeNotes }) {
      const rows = await db
        .select()
        .from(supportMessages)
        .where(and(eq(supportMessages.ticketId, ticketId), includeNotes ? undefined : ne(supportMessages.kind, "note")))
        .orderBy(asc(supportMessages.createdAt));
      const ids = rows.map((r) => r.id);
      const attachments = ids.length
        ? await db.select().from(supportAttachments).where(inArray(supportAttachments.messageId, ids))
        : [];
      return rows.map((row) => toMessage(row, attachments.filter((a) => a.messageId === row.id)));
    },

    async listStaleQueued(before) {
      const rows = await db
        .select()
        .from(supportMessages)
        .where(and(eq(supportMessages.deliveryStatus, "queued"), lt(supportMessages.createdAt, before)))
        .limit(100);
      return rows.map((row) => toMessage(row, []));
    },

    async insertAttachment(input) {
      const [row] = await db.insert(supportAttachments).values(input).returning();
      return toAttachment(row!);
    },

    async getAttachment(id) {
      const [row] = await db.select().from(supportAttachments).where(eq(supportAttachments.id, id)).limit(1);
      return row ? { ...toAttachment(row), ticketId: row.ticketId, uploadedBy: row.uploadedBy } : null;
    },

    async linkAttachments(ids, messageId) {
      if (!ids.length) return;
      await db
        .update(supportAttachments)
        .set({ messageId })
        .where(and(inArray(supportAttachments.id, ids), isNull(supportAttachments.messageId)));
    },

    async insertEvent(input) {
      await db.insert(supportEvents).values({ ...input, createdAt: input.createdAt ?? new Date() });
    },

    async listEvents(ticketId) {
      const rows = await db
        .select()
        .from(supportEvents)
        .where(eq(supportEvents.ticketId, ticketId))
        .orderBy(asc(supportEvents.createdAt));
      return rows as TicketEvent[];
    },

    async markRead(ticketId, readerId, at) {
      await db
        .insert(supportReads)
        .values({ ticketId, readerId, readAt: at })
        .onConflictDoUpdate({
          target: [supportReads.ticketId, supportReads.readerId],
          set: { readAt: sql`max(${supportReads.readAt}, excluded.read_at)` },
        });
    },

    async getReadTimes(ticketIds, readerId) {
      if (!ticketIds.length) return new Map();
      const rows = await db
        .select()
        .from(supportReads)
        .where(and(inArray(supportReads.ticketId, ticketIds), eq(supportReads.readerId, readerId)));
      return new Map(rows.map((r) => [r.ticketId, r.readAt]));
    },

    periodTotals: (range) => periodTotals(db, range),
    periodBreakdown: (range) => periodBreakdown(db, range),

    async getChannelState(channelId) {
      const [row] = await db
        .select()
        .from(supportChannelState)
        .where(eq(supportChannelState.channelId, channelId))
        .limit(1);
      return row?.state ?? null;
    },

    async setChannelState(channelId, state, error = null) {
      await db
        .insert(supportChannelState)
        .values({ channelId, state, lastError: error })
        .onConflictDoUpdate({
          target: supportChannelState.channelId,
          set: { state, lastError: error, updatedAt: new Date() },
        });
    },
  };
  return store;
}

function ticketFilters(query: Parameters<SupportStore["listTickets"]>[0]): (SQL | undefined)[] {
  const filters: (SQL | undefined)[] = [];
  if (query.status) filters.push(eq(supportTickets.status, query.status));
  else filters.push(ne(supportTickets.status, "spam"));
  if (query.assigneeId === null) filters.push(isNull(supportTickets.assigneeId));
  else if (query.assigneeId) filters.push(eq(supportTickets.assigneeId, query.assigneeId));
  if (query.customerId) filters.push(eq(supportTickets.customerId, query.customerId));
  if (query.channelId) filters.push(eq(supportTickets.channelId, query.channelId));
  if (query.createdFrom) filters.push(gte(supportTickets.createdAt, query.createdFrom));
  if (query.createdTo) filters.push(lt(supportTickets.createdAt, query.createdTo));
  if (query.topic) {
    // Raw SQL, so this file doesn't depend on the AI schema.
    filters.push(
      exists(
        sql`(select 1 from support_ticket_insights where support_ticket_insights.ticket_id = ${supportTickets.id} and support_ticket_insights.topic = ${query.topic})`
      )
    );
  }
  if (query.contactUserId) {
    filters.push(
      exists(
        sql`(select 1 from ${supportContacts} where ${supportContacts.id} = ${supportTickets.contactId} and ${supportContacts.userId} = ${query.contactUserId})`
      )
    );
  }
  const search = query.search?.trim();
  if (search) {
    // SQLite's LIKE is case-insensitive for ASCII; ESCAPE makes % and _ in the search literal.
    const pattern = `%${escapeLike(search)}%`;
    const number = /^#?(\d{1,9})$/.exec(search)?.[1];
    filters.push(
      or(
        sql`${supportTickets.subject} like ${pattern} escape '\\'`,
        number ? eq(supportTickets.number, Number(number)) : undefined,
        query.searchCustomerIds?.length ? inArray(supportTickets.customerId, query.searchCustomerIds) : undefined,
        exists(
          sql`(select 1 from ${supportContactIdentities} where ${supportContactIdentities.contactId} = ${supportTickets.contactId} and ${supportContactIdentities.value} like ${pattern} escape '\\')`
        ),
        exists(
          sql`(select 1 from ${supportContacts} where ${supportContacts.id} = ${supportTickets.contactId} and ${supportContacts.name} like ${pattern} escape '\\')`
        ),
        exists(
          sql`(select 1 from ${supportMessages} where ${supportMessages.ticketId} = ${supportTickets.id} and ${supportMessages.kind} <> 'note' and ${supportMessages.text} like ${pattern} escape '\\')`
        )
      )
    );
  }
  return filters;
}

function toContact(
  row: typeof supportContacts.$inferSelect,
  identities: (typeof supportContactIdentities.$inferSelect)[]
): Contact {
  return {
    id: row.id,
    name: row.name,
    customerId: row.customerId,
    userId: row.userId,
    locale: row.locale,
    blockedAt: row.blockedAt,
    identities: identities.map((i): Identity => ({ kind: i.kind, value: i.value })),
  };
}

function toAttachment(row: typeof supportAttachments.$inferSelect): Attachment {
  return {
    id: row.id,
    messageId: row.messageId,
    filename: row.filename,
    contentType: row.contentType,
    size: row.size,
    storageKey: row.storageKey,
    contentId: row.contentId,
    inline: row.inline,
  };
}

function toMessage(
  row: typeof supportMessages.$inferSelect,
  attachments: (typeof supportAttachments.$inferSelect)[]
): Message {
  return {
    ...row,
    kind: row.kind as Message["kind"],
    deliveryStatus: row.deliveryStatus as Message["deliveryStatus"],
    source: row.source as Message["source"],
    attachments: attachments.map(toAttachment),
  };
}

import { and, count, desc, eq, gte, inArray, isNotNull, lt, max, ne, sql, type SQL } from "drizzle-orm";
import type { BaseSQLiteDatabase } from "drizzle-orm/sqlite-core";
import { distributionFromRanks, type Distribution, type PeriodBreakdown, type PeriodTotals, type StatsRange } from "../insights";
import { supportEvents, supportTickets } from "./schema";

/*
 * Insights for SQLite and Cloudflare D1: the aggregate queries behind `support.stats()`. Every
 * query reads one period's tickets through `support_tickets_created_idx` or
 * `support_tickets_solved_idx` (0005_insights.sql) and answers in a handful of rows, so the
 * dashboard stays cheap to load with hundreds of thousands of tickets. `postgres/stats.ts` is the
 * same file in Postgres' dialect: the four helpers below are all that differs. Queries run one
 * after another, as everywhere in this store.
 */

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Db = BaseSQLiteDatabase<"async", any, any>;

/** A moment as a query parameter. */
export const at = (date: Date) => sql`${date.getTime()}`;
/** Milliseconds from one timestamp to a later one. */
export const elapsed = (later: SQL, earlier: SQL) => sql`(${later} - ${earlier})`;
/** Which day of a period a timestamp falls on, counting from 0. */
// The cast matters: a bound number may arrive as a real, and the division must still be whole days.
export const dayOf = (column: SQL, from: Date) => sql`cast((${column} - ${at(from)}) / 86400000 as integer)`;
const NO = sql.raw("0");

export const num = (value: SQL) => sql<number>`${value}`.mapWith(Number);

/** A reply that reached the customer: not an acknowledgement, not a failed send. */
export const isReply = (alias: string) =>
  sql.raw(`${alias}.kind = 'outbound' and ${alias}.auto = 0 and coalesce(${alias}.delivery_status, '') <> 'failed'`);

/**
 * The tickets opened in a range, as `r`: when the customer first wrote (`asked`) and when the
 * first reply after that reached them (`replied`, null while they wait). Tickets your team
 * started have no `asked`, so they never count as answered fast.
 */
export const firstReplies = (from: Date, to: Date) => sql`(
  select a.id, a.number, a.subject, a.status, a.waiting_since, a.asked,
    (select min(o.created_at) from support_messages o where o.ticket_id = a.id and ${isReply("o")} and o.created_at >= a.asked) as replied
  from (
    select t.id, t.number, t.subject, t.status, t.waiting_since,
      (select min(i.created_at) from support_messages i where i.ticket_id = t.id and i.kind = 'inbound' and i.auto = ${NO}) as asked
    from support_tickets t
    where t.created_at >= ${at(from)} and t.created_at < ${at(to)} and t.status <> 'spam'
  ) a
) r`;

/** How long each of those tickets waited, for the ones a target applies to: answered late, or still waiting. */
const waited = (now: Date) => sql`case when r.replied is not null then ${elapsed(sql`r.replied`, sql`r.asked`)} else ${elapsed(at(now), sql`r.asked`)} end`;
const isLate = (now: Date, targetMs: number) =>
  sql`r.asked is not null and (r.replied is not null or (r.status = 'open' and r.waiting_since is not null)) and ${waited(now)} > ${targetMs}`;

/**
 * The median and 90th percentile of `durations` (a derived table with one column, `d`), optionally
 * per group (a second column, `g`). The database ranks the values and hands back only the ranks
 * the two percentiles sit between.
 */
export async function distributions(db: Db, durations: SQL, grouped = false): Promise<Map<string, Distribution>> {
  const over = grouped ? sql.raw("partition by g") : sql.raw("");
  const rows = await db
    .select({ group: sql<string>`g`, rank: num(sql`rn`), value: num(sql`d`), n: num(sql`n`) })
    .from(
      sql`(select ${grouped ? sql.raw("g") : sql.raw("'all' as g")}, d, row_number() over (${over} order by d) as rn, count(*) over (${over}) as n from ${durations}) ranked`
    )
    .where(sql`rn in ((n - 1) * 5 / 10 + 1, (n - 1) * 5 / 10 + 2, (n - 1) * 9 / 10 + 1, (n - 1) * 9 / 10 + 2)`);
  const groups = new Map<string, typeof rows>();
  for (const row of rows) groups.set(String(row.group), [...(groups.get(String(row.group)) ?? []), row]);
  return new Map([...groups].map(([group, picked]) => [group, distributionFromRanks(picked)]));
}

const NONE: Distribution = { count: 0, median: null, p90: null };

export async function periodTotals(db: Db, { from, to, now, targetMs }: StatsRange): Promise<PeriodTotals> {
  const [opened] = await db
    .select({
      opened: num(sql`count(*)`),
      breaches: num(targetMs === null ? sql`0` : sql`coalesce(sum(case when ${isLate(now, targetMs)} then 1 else 0 end), 0)`),
    })
    .from(targetMs === null ? sql`(select 1 from support_tickets t where t.created_at >= ${at(from)} and t.created_at < ${at(to)} and t.status <> 'spam') r` : firstReplies(from, to));
  const firstReply = await distributions(
    db,
    sql`(select ${elapsed(sql`r.replied`, sql`r.asked`)} as d from ${firstReplies(from, to)} where r.replied is not null) durations`
  );

  const solvedIn = sql`t.solved_at >= ${at(from)} and t.solved_at < ${at(to)} and t.status = 'solved'`;
  const [solved] = await db
    .select({
      solved: num(sql`count(*)`),
      answered: num(sql`coalesce(sum(case when s.replies >= 1 then 1 else 0 end), 0)`),
      replies: num(sql`coalesce(sum(s.replies), 0)`),
      oneReply: num(sql`coalesce(sum(case when s.replies = 1 then 1 else 0 end), 0)`),
    })
    .from(sql`(select (select count(*) from support_messages o where o.ticket_id = t.id and ${isReply("o")}) as replies from support_tickets t where ${solvedIn}) s`);
  const timeToSolve = await distributions(db, sql`(select ${elapsed(sql`t.solved_at`, sql`t.created_at`)} as d from support_tickets t where ${solvedIn}) durations`);

  const [reopened] = await db
    .select({ tickets: num(sql`count(distinct ${supportEvents.ticketId})`) })
    .from(supportEvents)
    .where(and(eq(supportEvents.type, "reopened"), gte(supportEvents.createdAt, from), lt(supportEvents.createdAt, to)));

  return {
    opened: opened?.opened ?? 0,
    solved: solved?.solved ?? 0,
    reopened: reopened?.tickets ?? 0,
    firstReply: firstReply.get("all") ?? NONE,
    timeToSolve: timeToSolve.get("all") ?? NONE,
    breaches: targetMs === null ? null : (opened?.breaches ?? 0),
    answered: solved?.answered ?? 0,
    replies: solved?.replies ?? 0,
    oneReply: solved?.oneReply ?? 0,
  };
}

export async function periodBreakdown(db: Db, { from, to, now, targetMs, previousFrom }: StatsRange & { previousFrom: Date }): Promise<PeriodBreakdown> {
  const notSpam = ne(supportTickets.status, "spam");
  const isSolved = eq(supportTickets.status, "solved");
  const days = new Map<string, PeriodBreakdown["days"][number]>();
  const day = (index: number, channelId: string) => {
    const key = `${index}:${channelId}`;
    if (!days.has(key)) days.set(key, { day: index, channelId, opened: 0, solved: 0 });
    return days.get(key)!;
  };
  const openedRows = await db
    .select({ day: num(dayOf(sql`${supportTickets.createdAt}`, from)), channelId: supportTickets.channelId, tickets: count() })
    .from(supportTickets)
    .where(and(gte(supportTickets.createdAt, from), lt(supportTickets.createdAt, to), notSpam))
    .groupBy(sql`1`, sql`2`);
  for (const row of openedRows) day(row.day, row.channelId).opened = Number(row.tickets);
  const solvedRows = await db
    .select({ day: num(dayOf(sql`${supportTickets.solvedAt}`, from)), channelId: supportTickets.channelId, tickets: count() })
    .from(supportTickets)
    .where(and(gte(supportTickets.solvedAt, from), lt(supportTickets.solvedAt, to), isSolved))
    .groupBy(sql`1`, sql`2`);
  for (const row of solvedRows) day(row.day, row.channelId).solved = Number(row.tickets);

  // What is open now, walked back to `to` when the period ended earlier.
  const backlog = new Map<string, number>();
  const add = (rows: { channelId: string; tickets: number }[], sign: 1 | -1) => {
    for (const row of rows) backlog.set(row.channelId, (backlog.get(row.channelId) ?? 0) + sign * Number(row.tickets));
  };
  const byChannel = (where: SQL | undefined) =>
    db.select({ channelId: supportTickets.channelId, tickets: count() }).from(supportTickets).where(where).groupBy(supportTickets.channelId);
  add(await byChannel(inArray(supportTickets.status, ["open", "waiting"])), 1);
  if (to < now) {
    add(await byChannel(and(gte(supportTickets.createdAt, to), notSpam)), -1);
    add(await byChannel(and(gte(supportTickets.solvedAt, to), isSolved)), 1);
  }

  const agents = new Map<string | null, PeriodBreakdown["agents"][number]>();
  const agent = (agentId: string | null) => {
    if (!agents.has(agentId)) agents.set(agentId, { agentId, open: 0, waiting: 0, solved: 0, solvedBefore: 0 });
    return agents.get(agentId)!;
  };
  const load = await db
    .select({ agentId: supportTickets.assigneeId, status: supportTickets.status, tickets: count() })
    .from(supportTickets)
    .where(inArray(supportTickets.status, ["open", "waiting"]))
    .groupBy(supportTickets.assigneeId, supportTickets.status);
  for (const row of load) agent(row.agentId)[row.status as "open" | "waiting"] = Number(row.tickets);
  const solvedBy = await db
    .select({
      agentId: supportTickets.assigneeId,
      solved: num(sql`sum(case when ${supportTickets.solvedAt} >= ${at(from)} then 1 else 0 end)`),
      before: num(sql`sum(case when ${supportTickets.solvedAt} < ${at(from)} then 1 else 0 end)`),
    })
    .from(supportTickets)
    .where(and(gte(supportTickets.solvedAt, previousFrom), lt(supportTickets.solvedAt, to), isSolved))
    .groupBy(supportTickets.assigneeId);
  for (const row of solvedBy) Object.assign(agent(row.agentId), { solved: row.solved, solvedBefore: row.before });

  const top = await db
    .select({ customerId: supportTickets.customerId, tickets: count() })
    .from(supportTickets)
    .where(and(gte(supportTickets.createdAt, from), lt(supportTickets.createdAt, to), notSpam, isNotNull(supportTickets.customerId)))
    .groupBy(supportTickets.customerId)
    .orderBy(desc(count()), supportTickets.customerId)
    .limit(8);
  const topIds = top.map((row) => row.customerId!);
  const earlier = topIds.length
    ? await db
        .select({ customerId: supportTickets.customerId, tickets: count() })
        .from(supportTickets)
        .where(and(gte(supportTickets.createdAt, previousFrom), lt(supportTickets.createdAt, from), notSpam, inArray(supportTickets.customerId, topIds)))
        .groupBy(supportTickets.customerId)
    : [];
  const before = new Map(earlier.map((row) => [row.customerId, Number(row.tickets)]));

  const reopened = await db
    .select({ id: supportTickets.id, number: supportTickets.number, subject: supportTickets.subject, at: max(supportEvents.createdAt) })
    .from(supportEvents)
    .innerJoin(supportTickets, eq(supportTickets.id, supportEvents.ticketId))
    .where(and(eq(supportEvents.type, "reopened"), gte(supportEvents.createdAt, from), lt(supportEvents.createdAt, to)))
    .groupBy(supportTickets.id, supportTickets.number, supportTickets.subject)
    .orderBy(desc(max(supportEvents.createdAt)), desc(supportTickets.number))
    .limit(5);

  const late =
    targetMs === null
      ? []
      : await db
          .select({
            id: sql<string>`r.id`,
            number: num(sql`r.number`),
            subject: sql<string | null>`r.subject`,
            waitedMs: num(waited(now)),
            answered: num(sql`case when r.replied is not null then 1 else 0 end`),
          })
          .from(firstReplies(from, to))
          .where(isLate(now, targetMs))
          .orderBy(sql`4 desc`, sql`2 desc`)
          .limit(5);

  return {
    days: [...days.values()].sort((a, b) => a.day - b.day || a.channelId.localeCompare(b.channelId)),
    backlog: [...backlog].map(([channelId, tickets]) => ({ channelId, tickets })),
    agents: [...agents.values()],
    customers: top.map((row) => ({ customerId: row.customerId!, tickets: Number(row.tickets), before: before.get(row.customerId) ?? 0 })),
    reopened: reopened.map((row) => ({ ...row, at: row.at! })),
    late: late.map((row) => ({ ...row, answered: row.answered === 1 })),
  };
}

CREATE INDEX `support_events_type_idx` ON `support_events` (`type`,`created_at`);--> statement-breakpoint
CREATE INDEX `support_tickets_created_idx` ON `support_tickets` (`created_at`);--> statement-breakpoint
CREATE INDEX `support_tickets_solved_idx` ON `support_tickets` (`solved_at`);
